const std = @import("std");

const crypto = @import("crypto.zig");

const HASH_TREE_HEIGHT = 64;
const LEFT_SALT = 'L';
const RIGHT_SALT = 'R';

pub const Subscription = struct {
    /// Minimal representation of a subscription in memory
    pub const Bytes = extern struct {
        start: u64,
        end: u64,
        root_hashes: [126][24]u8 = undefined,
    };

    serialized: Bytes,
    roots: [126]RootPosition = undefined,
    cached_hashes: [][24]u8 = undefined,
    root_index: isize = -1,
    last_timestamp: u64 = 0,

    pub inline fn asBytes(self: *Subscription) []u8 {
        return std.mem.asBytes(&self.serialized);
    }

    pub fn init(start: u64, end: u64, root_hash_bytes: []const u8) Subscription {
        if (start > end) {
            @panic("Invalid range: a > b");
        }

        var self: Subscription = .{
            .serialized = .{ .start = start, .end = end },
            .cached_hashes = std.heap.c_allocator.alloc([24]u8, 65) catch @panic("OOM"),
        };

        var iter = std.mem.window(u8, root_hash_bytes, 24, 24);
        var i: usize = 0;
        while (iter.next()) |hash| {
            @memcpy(&self.serialized.root_hashes[i], hash);
            i += 1;
        }

        self.calculateRootPositions();

        return self;
    }

    pub fn deinit(self: *Subscription) void {
        std.heap.c_allocator.free(self.cached_hashes);
    }

    fn calculateRootPositions(self: *Subscription) void {
        if (self.serialized.start == 0 and self.serialized.end == std.math.maxInt(u64)) {
            self.roots[0] = RootPosition{ .offset = 0, .power = 64 };
            return;
        }

        var index: usize = 0;
        var start = self.serialized.start;

        while (start <= self.serialized.end) {
            const power = @min(@as(u6, @intCast(@bitSizeOf(u64) - 1 - @clz(self.serialized.end - start + 1))), @ctz(start));

            self.roots[index] = RootPosition{ .offset = start, .power = power };
            index += 1;

            start += @as(u64, 1) << power;
        }
    }

    pub fn getKey(self: *Subscription, timestamp: u64) [24]u8 {
        if (timestamp > self.serialized.end) @panic("Timestamp past end of subscription");
        if (timestamp < self.last_timestamp) @panic("Decreasing timestamp");

        // Calculate the number of lower bits changed
        var hash_index = 64 - @clz(self.last_timestamp ^ timestamp);

        self.last_timestamp = timestamp;

        const root_index: usize = @intCast(self.root_index + 1);
        for (self.roots[root_index..], root_index..) |root, i| {
            if (root.includes(timestamp)) {
                self.root_index = @intCast(i);
                hash_index = root.power;
                @memcpy(&self.cached_hashes[root.power], &self.serialized.root_hashes[i]);
                break;
            }
        }

        var i = hash_index;
        while (i > 0) : (i -= 1) {
            var hasher = std.crypto.hash.Blake3.init(.{});
            hasher.update(&self.cached_hashes[i]);
            hasher.update(&[_]u8{if (timestamp & (@as(u64, 1) << @truncate(i - 1)) == 0) LEFT_SALT else RIGHT_SALT});
            hasher.final(&self.cached_hashes[i - 1]);
        }
        return self.cached_hashes[0];
    }
};

const RootPosition = struct {
    offset: u64,
    power: u7,

    inline fn start(self: RootPosition) u64 {
        return self.offset;
    }

    inline fn end(self: RootPosition) u64 {
        if (self.power == 64) return std.math.maxInt(u64);
        return self.offset + (@as(u64, 1) << @truncate(self.power)) - 1;
    }

    inline fn includes(self: RootPosition, timestamp: u64) bool {
        return timestamp >= self.start() and timestamp <= self.end();
    }
};

test "ctz" {
    try std.testing.expectEqual(64, @ctz(@as(u64, 0)));
}

test "getKey" {
    const root_hashes: []const [24]u8 = &[_][24]u8{
        .{ 27, 85, 15, 241, 245, 1, 184, 108, 61, 75, 94, 31, 186, 159, 165, 231, 202, 106, 210, 107, 175, 133, 213, 171 },
        .{ 67, 160, 241, 104, 185, 171, 129, 66, 88, 183, 161, 50, 47, 216, 229, 73, 151, 14, 60, 188, 88, 2, 103, 200 },
        .{ 209, 54, 62, 114, 217, 2, 18, 160, 148, 155, 104, 119, 34, 205, 202, 233, 111, 127, 42, 141, 86, 137, 146, 197 },
        .{ 5, 165, 98, 21, 118, 240, 244, 147, 42, 182, 3, 173, 252, 45, 192, 168, 171, 248, 47, 145, 167, 156, 188, 134 },
    };

    var subscription = Subscription.init(1, 6, std.mem.sliceAsBytes(root_hashes));
    try std.testing.expectEqualDeep(&[_]RootPosition{
        .{ .offset = 1, .power = 0 },
        .{ .offset = 2, .power = 1 },
        .{ .offset = 4, .power = 1 },
        .{ .offset = 6, .power = 0 },
    }, subscription.roots[0..4]);

    {
        const key = subscription.getKey(2);
        try std.testing.expectEqual(bytes("8c47ca6a93f55fb40b9674cb64d2634da741fa9432fc6478"), key);

        var frame_data = bytes("04f9c52cc6aeeabb44176c10ce4bb7318a53a2de96fdabf22d964974339bde5722c153eef203372728fa91146bcdd74fac0ffe14ff2b8de9a8449bab6e06d911");
        crypto.decrypt(&frame_data, key);
        try std.testing.expectEqualStrings("Hello world!----------------------------------------------------", &frame_data);
    }

    try std.testing.expectEqual(bytes("72038fa029f797fbe1615792c666a16343633f6f0398ba49"), subscription.getKey(3));
    try std.testing.expectEqual(bytes("8afe6e15af82e2cf5a9e98e274e7b0f7337c92a9956a863c"), subscription.getKey(4));
}

test "getKey largest range" {
    const root_hashes: []const [24]u8 = &[_][24]u8{
        .{ 92, 41, 135, 21, 199, 72, 213, 178, 155, 32, 7, 238, 113, 7, 159, 182, 125, 146, 171, 77, 75, 54, 49, 192 },
    };

    var subscription = Subscription.init(0, std.math.maxInt(u64), std.mem.sliceAsBytes(root_hashes));
    try std.testing.expectEqualDeep(&[_]RootPosition{
        .{ .offset = 0, .power = 64 },
    }, subscription.roots[0..1]);

    try std.testing.expectEqual(bytes("3211aa2b56436729e010de5ba6fceee544e09e39f706767e"), subscription.getKey(0));
    try std.testing.expectEqual(bytes("1b550ff1f501b86c3d4b5e1fba9fa5e7ca6ad26baf85d5ab"), subscription.getKey(1));
    try std.testing.expectEqual(bytes("ee6d906f2e1136b643ec383d8a61e42f0fac959bab8ea137"), subscription.getKey(150));
    try std.testing.expectEqual(bytes("d9ceb3d9c9df5242fda778f999d13ca0404f99cfa5422ec3"), subscription.getKey(0xdeadbeefcafebabe));

    var frame_data = bytes("8b77b010a5810b4849d7d4799af6300738848dc82f6517044e5c57c379db9b4cf01b183073060a690b3c1503f12d174ca5093dfb0927f231c2372c56790a9c8c");
    crypto.decrypt(&frame_data, subscription.getKey(0xdeadbeefcafebabe));
    try std.testing.expectEqualStrings("Hola Mundo------------------------------------------------------", &frame_data);
}

test "getKey single value range" {
    const root_hashes: []const [24]u8 = &[_][24]u8{
        .{ 138, 254, 110, 21, 175, 130, 226, 207, 90, 158, 152, 226, 116, 231, 176, 247, 51, 124, 146, 169, 149, 106, 134, 60 },
    };

    var subscription = Subscription.init(4, 4, std.mem.sliceAsBytes(root_hashes));
    try std.testing.expectEqualDeep(&[_]RootPosition{
        .{ .offset = 4, .power = 0 },
    }, subscription.roots[0..1]);

    const key = subscription.getKey(4);
    try std.testing.expectEqual(bytes("8afe6e15af82e2cf5a9e98e274e7b0f7337c92a9956a863c"), key);

    var frame_data = bytes("5f0cd96b263823ed35fe8844a352933a7dbf0db4caf706d781af22ff8263461ac87e7cea209cc78902002e5007da61d3cde331b20c2b0577a23eb0d6c537ca5b");
    crypto.decrypt(&frame_data, key);
    try std.testing.expectEqualStrings("Hallo welt------------------------------------------------------", &frame_data);
}

